const source = new URL(context.url);
if (!['https:', 'http:'].includes(source.protocol)) return;
const values = await api.input.request({ title: 'Save to shopping shortlist', fields: [
  { key: 'product', label: 'Product name (blank uses page title)', type: 'text' },
  { key: 'price', label: 'Displayed price and currency', type: 'text', required: true, placeholder: 'e.g. ₦850,000 or $129.99' },
  { key: 'details', label: 'Variant, condition or comparison notes', type: 'textarea' }
] });
if (!values) return;
const product = (values.product.trim() || context.title || source.hostname).slice(0, 110);
api.notes.create({ title: product, body: '# Shopping shortlist\n\nProduct: ' + product + '\n\nPrice when saved: ' + values.price.trim() + '\n\nDetails: ' + (values.details.trim() || context.selection?.trim() || 'None added') + '\n\nSource: <' + source.href.replace(/>/g, '%3E') + '>\nSaved: ' + new Date().toISOString().slice(0, 10) });
